/* 1.气泡层 */
.mes {
  position: relative;
  z-index: -2;
  background-attachment: local; 
  transition: transform 0.2s ease; 
  transform-origin: top center;
  max-width: 400px;/*💽气泡层大小，也就是适配手机的尺寸大小，自己尝试适配多少px*/
  width:100%;
  margin: 220px auto 80px !important; /*💽历史和最新消息的间缝大小*/
  background-size: 400px auto; /*💿这里同样改尺寸大小，以防万一*/
  padding-top: 10px !important; 
  padding-bottom: 50px !important; 
  transform: scale(1) rotate(0deg) !important;
  background-image: url('https://iili.io/qdFafv2.png'); 
  background-repeat: repeat-y;
  background-position: top center;
  overflow: visible;
  border: 0 !important;
  outline: 0 !important;
  box-shadow: none !important; 
}

/*上层装饰层*/
.mes::after {
  content: '';
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  width: 400px !important ;/*💽装饰层尺寸大小，解释和上面气泡层尺寸一样*/
  max-width: none !important;
  height: 220px;
  background-image: url('');
  background-size: 100% auto; 
  background-repeat: no-repeat;
  background-position: center top;
  pointer-events: none;
  z-index: -1;
  top: -165px !important; /*💽上下*/
}

/*下层装饰层-没做*/
.mes::before {
  content: "";
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  width: 400px !important;
  max-width: none !important;
  height: 220px;
  background-image: url('');
  background-repeat: no-repeat;
  background-size: 100% auto; 
  background-position: center bottom;
  z-index: -1;
  pointer-events: none;
  bottom: -0px !important;  /*💽上下*/
}


/* ========头像与头像框========= */
/* 头像容器位置 */
.mesAvatarWrapper {
    position: absolute !important;
    top: -115px !important;    /* 💽上下微调 */
    left: 50% !important;   /* 💽左右微调 */
    transform: translateX(-50%) !important;
    width: auto !important;
    height: auto !important;
    padding: 0 !important;
    margin: 0 !important;
    z-index: 1 !important;
    overflow: visible !important;
    filter: none !important;
    box-shadow: none !important;
}


/* 头像本体 */
.mesAvatarWrapper .avatar {
    width: 100px;  
    height: 100px;
    transform: scale(4) rotate(0deg) !important; /* 💽缩放与旋转 */
    transform-origin: center center !important;
    max-width: unset !important;
    max-height: unset !important;
    clip-path: inset(15% 0 35% 0);
}

.mesAvatarWrapper .avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    box-shadow: none !important;
}

/* 头像框 */
.mesAvatarWrapper::after {
    content: '';
    position: absolute;
    top: 12% !important;   /* 💽上下 */
    left: 50% !important;  /* 💽左右 */
    width: 100% !important;
    height: 100% !important;
    transform: translate(-50%, -50%) scale(4) rotate(0deg) !important; /*💽头像框大小*/
    background-image: url('https://iili.io/q3ODbol.png');
    background-size: contain !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    pointer-events: none;
    z-index: 1;
}

/* .2.名字与时间戳 */
/*必要的前置*/
.mes_block {
    position: relative !important;
    overflow: visible !important; 
    margin-top: 0px; 
    z-index: auto;
}

/* 💽名字 */
.name_text {
    position: absolute !important;
    z-index: 10;
    top: -25px !important;      /* 💽上下微调 */
    left: 1% !important;       /* 💽左右微调 */
    transform: rotate(0deg) !important; 
    width: auto !important;
    text-align: center !important; 
    font-size: 12px !important;
    font-weight: 700 !important;
    white-space: nowrap !important;
    color: #fff !important; 
    opacity: 1;
    -webkit-text-stroke: 0px #ffffff !important;
    paint-order: stroke fill !important;
   pointer-events: none;
}


.name_text::before {
    content: ''; 
    display: inline-block;
    margin-right: -2px;
    color: inherit;
    pointer-events: none;
}

.name_text::after {
    content: '.text'; 
    display: inline-block;
    margin-left: 0px;
    pointer-events: none;
}


/* 💽时间戳 */
.timestamp {
    position: absolute !important;
    z-index: 9;
    top: -23px !important;     /* 💽上下微调 */
    left: 282px !important;    /* 💽左右微调 */
    font-size: 10px !important;
    font-weight: 500 !important;
    white-space: nowrap !important;
    color: #fff !important;
    opacity: 1;
}

.timestamp::before {
    content: '';
    display: inline-block;
    margin-right: 0px;
}

.timestamp::after {
    content: '';
    display: inline-block;
    margin-left: 0px;
}

/* 3. 三元素信息 (楼层、计时、词符) */
/* 楼层数 */
.mesIDDisplay {
    position: absolute !important;
    z-index: 9;
    top: 102px !important;   /* 💽上下微调 */
    left: 35px !important;    /* 💽左右微调 */;
    font-size: 10px !important;
    font-weight: 500 !important;
    white-space: nowrap !important;
    color: #fff !important; ;
    opacity: 1 !important;
}

.mesIDDisplay::before {
    content: ''; 
    display: inline-block;
    margin-right: -5px;
}

.mesIDDisplay::after {
    content: ''; 
    display: inline-block;
    margin-left: 5px;
}

/* 回复计时 */
.mes_timer {
    position: absolute !important;
    z-index: 9;
    top: var(--element-top, -90px) !important; /* 💽上下微调 */
    left: var(--element-left,-105px) !important;/* 💽左右微调 */
    transform: rotate(0deg);
    font-size: 8px !important;
    font-weight: 500 !important;
    color: #fff !important; 
    white-space: nowrap;
    cursor: default;
    opacity: 0.7 !important;
}

.mes_timer::before {
    content: ''; 
    display: inline-block;
    margin-right: 2px;
}

.mes_timer::after {
    content: '';
    display: inline-block;
    margin-left: 2px;
}

/* 词符数 */
.tokenCounterDisplay {
    position: absolute !important;
    z-index: 10;
    top: 102px !important;     /* 💽上下微调 */
    left: 93px !important;    /* 💽左右微调 */
    transform: translateX(-50%) rotate(0deg);
    font-size: 10px !important;
    font-weight: 500 !important;
    color: #fff !important; 
    -webkit-text-stroke: 0px #ffffff !important;
    paint-order: stroke fill !important;
    white-space: nowrap;
    opacity: 1 !important;
}

.tokenCounterDisplay::before {
    content: '文件占用内存 ';
    display: inline-block;
    margin-right: 0px;
}

.tokenCounterDisplay::after {
    content: '';
    display: inline-block;
    margin-left: 0px;
}

/* 4. 操作按钮 (小铅笔、复制等 - 平时状态) */
.mes_buttons {
    position: absolute !important;
    z-index: 9;
    top: -0px !important;      /* 💽上下位置 */
    right: 10px !important;    /* 💽左右位置 */
    display: flex;             
    flex-direction: row;       
    align-items: center;
    margin: 0 !important;
    padding: 0 !important;
    opacity: 1 !important;         
}

.mes[typing="true"] .mes_buttons {
    display: none !important;
    opacity: 0 !important;
    pointer-events: none !important;
}

.mes_buttons > div,
.mes_buttons button {
    opacity: 1 !important;
    visibility: visible !important;
}

.mes_buttons[style*="display: none"],
.mes_buttons[style*="display:none"] {
    display: none !important;
    opacity: 1 !important;
}


/* 编辑状态菜单 */
.mes_edit_buttons {
    position: absolute !important;
    z-index: 15;
    top: -0px !important;      /* 💽上下微调 */
    right: 40px !important;   /* 💽左右微调 */
    flex-direction: row;
    align-items: center;
    gap: 10px;        
    opacity: 1 !important; 
    display: none; 
}

/* 去除编辑、删除、重生成等按钮的阴影和发光 */
.mes_buttons div, 
.mes_edit,
.mes_text_paste {
    text-shadow: none !important;  /* 去除字体发光/阴影 */
    box-shadow: none !important;   /* 去除盒子边框阴影 */
    filter: none !important;       /* 去除滤镜产生的投影 */
}

.mes_buttons div:hover,
.mes_edit:hover {
    text-shadow: none !important;
}


.mes_buttons,
.mes .mes_buttons,
.mes:hover .mes_buttons {
    opacity: 1 !important;
}

/* -5. 文本框主体 (Text)- */
/* --- User (用户) 文本框 --- */
.mes[is_user="true"] .mes_text {
    padding-top: 10px !important;    /* 💽加大数值=文字下移，减小=文字上移 */
    margin-top: 10px !important;/*💿同上*/
    padding-bottom: 15px !important; /* 💽底部留白 */
    padding-left: 5px !important;   /* 💽左侧留白 */
    padding-right: 15px !important;  /* 💽右侧留白 */
    min-height: 0px !important;  
    text-align: justify; 
}

/* --- Char (角色) 文本框 --- */
.mes[is_user="false"] .mes_text {
    padding-top: -60px !important;    /* 💽加大数值=文字下移，减小=文字上移 */
    margin-top: -60px !important;/*💿同上*/
    padding-bottom: 0px !important; /* 💽底部留白 */
    padding-left: 3.5px !important;   /* 💽左侧留白 */
    padding-right: 13.5px !important; /* 💽右侧留白 */
    min-height: 0px !important;
    text-align: justify;
}


/*杂七杂八的东西*/
.mesIDDisplay, .mes_timer, .tokenCounterDisplay, .name_text, .timestamp {
    position: absolute !important;
    z-index: 9;
    width: auto !important;
    white-space: nowrap !important;
    pointer-events: none; 
}


